using System;
using UnityEngine;

namespace DeadCounty.Audio
{
    // Mixer bus of a cue: each has its own volume in the settings, Interface and Music keep playing while paused.
    public enum SoundChannel { Effects, Ambience, Music, Interface }

    // A family of interchangeable clips (footsteps on gravel, a door creak) with their playback settings.
    // Generated by the scene builder; play it through Sfx.
    [CreateAssetMenu(menuName = "DeadCounty/Sound Cue")]
    public sealed class SoundCue : ScriptableObject
    {
        public AudioClip[] clips;
        [Range(0f, 1f)] public float volume = 1f;
        public Vector2 pitch = new(0.95f, 1.05f);
        public SoundChannel channel = SoundChannel.Effects;
        public float minDistance = 1f;
        public float maxDistance = 25f;

        [NonSerialized] int last = -1;

        // Random clip, never the same one twice in a row when there are two or more: repeats are what make
        // footsteps sound mechanical.
        public AudioClip Pick()
        {
            if (clips == null || clips.Length == 0) return null;
            if (clips.Length == 1) return clips[0];
            int index;
            if (last < 0 || last >= clips.Length)
                index = UnityEngine.Random.Range(0, clips.Length);
            else
            {
                index = UnityEngine.Random.Range(0, clips.Length - 1);
                if (index >= last) index++;
            }
            last = index;
            return clips[index];
        }

        public float RandomPitch() => UnityEngine.Random.Range(pitch.x, pitch.y);
    }
}
